const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
function announce(message){let e=$('#toast');if(!e){e=document.createElement('div');e.id='toast';e.className='toast';e.setAttribute('role','status');document.body.append(e)}e.textContent=message;e.hidden=false;clearTimeout(window.noticeTimer);window.noticeTimer=setTimeout(()=>e.hidden=true,4800)}
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
$$('[data-open]').forEach(b=>b.addEventListener('click',()=>{const d=document.getElementById(b.dataset.open);d.showModal()}));
$$('[data-age]').forEach(b=>b.addEventListener('click',()=>{$$('[data-age]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const a=$('#age-copy');if(a)a.textContent=b.dataset.age==='3-4'?'للصغار: اكتشاف لونين مع ولي الأمر.':b.dataset.age==='5-6'?'نتدرّب معًا على التصنيف بالأشكال والألوان.':'تحدٍ أكبر: نرتّب نمطًا ونشرح كيف اخترناه.';}));
$$('[data-child]').forEach(b=>b.addEventListener('click',()=>{$$('[data-child]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const older=b.dataset.child==='adam';$$('[data-child-name]').forEach(x=>x.textContent=older?'آدم':'ليان');$('#task-title').textContent=older?'ماذا يأتي بعد؟':'كل شكل له حكاية';$('#task-description').textContent=older?'رتّبا نمطًا من ثلاثة ألوان، ثم اسأليه: كيف عرفت اللون التالي؟':'اختارا ثلاثة أشكال من حولكما، ثم اجمعا الأشكال المتشابهة.';$('#activity-count').textContent=older?'٣':'٤';$('#weekly-count').textContent=older?'٣ من ٤ أنشطة':'٤ من ٥ أنشطة';$('#weekly-bar').style.width=older?'75%':'80%';$('#coach-copy').textContent=older?'آدم يجرّب أنماطًا جديدة. اسأليه عن طريقته قبل أن تعطيه تلميحًا.':'جرّبي أن تطلبي من ليان شرح اختيارها. الحوار حول الفكرة جزء من النشاط.';$('#child-age').textContent=older?'٧ سنوات':'٥ سنوات';$('#child-link').href='child.html?child='+b.dataset.child;announce('تُعرض الآن بيانات '+(older?'آدم':'ليان')+' التجريبية.')}));
const form=$('#demo-form');if(form){let step=1;form.addEventListener('submit',e=>{e.preventDefault();if(step===1){if(!form.reportValidity())return;step=2;$('#auth-one').hidden=true;$('#auth-two').hidden=false;$('#auth-title').textContent='لنتعرّف إلى طفلك';$('#auth-intro').textContent='اسم مستعار وفئة عمرية لاختيار بداية مناسبة.';$('#email').disabled=true;$('#consent').disabled=true;$('#nickname').required=true;$('#age').required=true;$('#auth-submit').textContent='شاهدي لوحة المتابعة';$('#nickname').focus();}else{if(!form.reportValidity())return;window.location.href='parent.html';}});}
const choices=$$('.choice');if(choices.length){const params=new URLSearchParams(location.search);if(params.get('child')==='adam')$('#child-greeting').textContent='مرحبًا يا آدم!';choices.forEach(b=>b.addEventListener('click',()=>{choices.forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});if(b.dataset.answer==='circle'){$('#feedback').textContent='أحسنت! الدائرة ليس لها زوايا.';$('#next-step').hidden=false;$('#progress-two').classList.add('done')}else{$('#feedback').textContent='لنجرب معًا: ابحث عن شكل بلا زوايا.';$('#next-step').hidden=true}}));$('#next-step').addEventListener('click',()=>{$('#child-question').textContent='والآن، نكتشف خارج الشاشة!';$('#child-instruction').textContent='ابحث مع أحد والديك عن شيء دائري في الغرفة.';$('.choices').hidden=true;$('#feedback').textContent='قل له: ما الذي جعلني أختاره؟';$('#next-step').hidden=true;$('#finish-step').hidden=false;$('#progress-three').classList.add('done')});$('#finish-step').addEventListener('click',()=>{$('#child-question').textContent='يا لها من رحلة جميلة!';$('#child-instruction').textContent='رأيت الشكل، واخترته، ووجدته حولك.';$('#feedback').textContent='كل محاولة تساعدنا على التعلّم.';$('#finish-step').hidden=true;$('#restart-step').hidden=false});$('#restart-step').addEventListener('click',()=>location.reload())}
const search=$('#queue-search');if(search){let current='all';function filter(){let n=0;$$('#queue-body tr').forEach(row=>{const show=row.textContent.includes(search.value)&&(current==='all'||row.dataset.status===current);row.hidden=!show;if(show)n++});$('#queue-count').textContent=n?'عرض '+n+' طلبات تجريبية':'لا توجد طلبات تطابق البحث';}search.addEventListener('input',filter);$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{current=b.dataset.filter;$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));filter()}));$$('[data-review]').forEach(b=>b.addEventListener('click',()=>{window.activeRow=b.closest('tr');$('#review-title').textContent=$('strong',window.activeRow).textContent;$('#review-dialog').showModal()}));$('#approve-demo').addEventListener('click',()=>{window.activeRow.dataset.status='approved';$('.tag',window.activeRow).textContent='معتمد';$('.tag',window.activeRow).className='tag';$('#review-dialog').close();filter();announce('تغيّرت حالة الطلب في هذه المعاينة فقط. لم تُرسل أي موافقة إلى النظام الفعلي.')});}
$$('[data-notice]').forEach(b=>b.addEventListener('click',()=>announce(b.dataset.notice)));
